function pumpkin(p,x,z,s=.45){let g=group(p,x,.08,z);for(let j=0;j<8;j++){let a=j*Math.PI/4;ball(g,Math.cos(a)*s*.32,s*.45,Math.sin(a)*s*.32,s*.37,s*.45,s*.37,j%2?'#cf974e':'#dda355')}tube(g,[[0,s*.83,0],[.03,s*1.1,0],[.12,s*1.18,.01]],.038,'#8b8e68');for(let side of [-1,1]){let eye=mesh(new T.ConeGeometry(s*.105,s*.13,3),'#fff0a8',g,side*s*.2,s*.5,s*.58);eye.rotation.x=Math.PI/2;eye.rotation.z=side*.25}tube(g,[[-s*.25,s*.25,s*.52],[0,s*.15,s*.57],[s*.25,s*.25,s*.52]],.018,'#fff0b0');return interactive(g,'pumpkin','Réveiller la citrouille')}
function lantern(p,x,z){let g=group(p,x,0,z);cylinder(g,0,.55,0,.024,1.1,'#948270');let hook=torus(g,.10,1.05,0,.11,.015,'#948270');cube(g,.19,.84,0,.23,.29,.23,'#efd49b');cube(g,.19,.68,0,.27,.025,.27,'#8b7b67');let roof=mesh(new T.ConeGeometry(.22,.15,4),'#8b7b67',g,.19,1.05,0);roof.rotation.y=Math.PI/4;for(let sx of [-1,1])for(let sz of [-1,1])cube(g,.19+sx*.105,.84,sz*.105,.018,.29,.018,'#9b856b');let glow=new T.PointLight('#ffd39a',.8,2);glow.position.set(.19,.84,0);g.add(glow);return interactive(g,'lantern','Allumer la lanterne')}
function snowman(p,x,z){let g=group(p,x,0,z);ball(g,0,.35,0,.36,.38,.35,'#f1f2ec');ball(g,0,.87,0,.26,.28,.25,'#f5f3ed');for(let side of [-1,1]){ball(g,side*.085,.94,.23,.025,.025,.025,'#53606b');tube(g,[[side*.2,.56,0],[side*.42,.64,.02],[side*.54,.82,.03]],.024,'#9d8872')}
let nose=mesh(new T.ConeGeometry(.04,.4,16),'#dca05c',g,0,.86,.4);nose.rotation.x=Math.PI/2;cylinder(g,0,1.15,0,.27,.035,'#687a86');cylinder(g,0,1.23,0,.17,.16,'#697985');let scarf=torus(g,0,.67,0,.235,.04,'#c58d85');scarf.rotation.x=Math.PI/2;cube(g,.14,.5,.27,.095,.3,.03,'#c58d85');for(let i=0;i<3;i++)ball(g,0,.2+i*.12,.34,.024,.024,.019,'#72818a');return interactive(g,'snowman','Lancer une boule de neige')}
function pond(p,x,z,theme){let g=group(p,x,0,z);for(let i=0;i<12;i++){let a=i*Math.PI/6;ball(g,Math.cos(a)*.95,.07,Math.sin(a)*.66,.17,.1,.12,'#b0b6a4')}let water=mesh(new T.CircleGeometry(1,48),'#88bec2',g,0,.065,0,{metalness:.22,roughness:.22});water.rotation.x=-Math.PI/2;water.scale.y=.67;let duck=group(g,0,.12,0);ball(duck,0,.04,0,.13,.08,.09,'#edcf79');ball(duck,.10,.13,0,.074,.075,.065,'#f0d383');ball(duck,.17,.13,0,.04,.016,.035,'#dba262');ball(duck,.12,.15,.052,.009,.009,.009,'#515967');g.userData.duck=duck;return interactive(g,'pond',theme==='winter'?'Faire glisser le canard sur la glace':'Faire barboter le canard')}
// Batch repeated static meshes while keeping parent groups pickable and animatable.
function batchStatic(g){
 if(g.userData.actor)return;
 for(const child of [...g.children])if(child.isGroup)batchStatic(child);
 const batches=new Map();
 for(const child of g.children)if(child.isMesh&&!child.isInstancedMesh&&!Array.isArray(child.material)){
  let k=child.geometry.uuid+':'+child.material.uuid;if(!batches.has(k))batches.set(k,[]);batches.get(k).push(child);
 }
 for(const list of batches.values())if(list.length>=3){let inst=new T.InstancedMesh(list[0].geometry,list[0].material,list.length);inst.castShadow=true;inst.receiveShadow=true;
  list.forEach((o,i)=>{o.updateMatrix();inst.setMatrixAt(i,o.matrix);g.remove(o)});inst.computeBoundingSphere();g.add(inst);
 }
}
export function makeMap(theme){let p=palettes[theme],root=new T.Group(),props=[],extras=[],actors=[];
let floor=cube(root,0,-.16,0,60,.28,60,p.grass);floor.castShadow=false;let sidewalk=cube(root,0,.002,0,9.2,.035,7.7,p.path);cube(root,0,.025,0,7.5,.055,6.1,p.grass);for(let i=0;i<30;i++){let a=i*Math.PI*2/30;ball(root,Math.cos(a)*8.4,.025,Math.sin(a)*6,.32,.06,.17,theme==='winter'?'#eaf0ee':'#b5bc95')}
const add=g=>{props.push(g);return g};add(house(root,-5.5,-3.3,theme));add(tree(root,-6.1,1.9,theme,1.1));add(tree(root,5.4,-3.2,theme,1.2));add(tree(root,6.5,1.6,theme,.85));add(bench(root,-5.2,.1));add(pond(root,5,1.1,theme));
for(let j=0;j<4;j++){let z=-4+j*2.1;let g=theme==='summer'?umbrella(root,j%2?-5.2:5.5,z):theme==='autumn'?pumpkin(root,j%2?-5:5.2,z,.4+j*.035):theme==='winter'?snowman(root,j%2?-5.3:5.3,z):garden(root,j%2?-5.2:5.2,z,theme);if(j<2)add(g);else{extras.push(g);g.visible=false;g.userData.threshold=8+j*4}}
for(let j=0;j<8;j++){let g=theme==='autumn'?lantern(root,-3.7+j*1.05,-4.3):theme==='winter'?snowman(root,-3.7+j*1.05,-4.3):theme==='summer'?garden(root,-3.7+j*1.05,-4.3,'summer'):garden(root,-3.7+j*1.05,-4.3,theme);g.scale.setScalar(.6);g.userData.baseScale=.6;g.userData.threshold=3+j*4;g.visible=false;extras.push(g);props.push(g)}
for(let j=0;j<4;j++){let g=character(theme,j);g.position.set(-4.2+j*2.6,0,3.7);root.add(g);actors.push(g)}
for(let j=0;j<10;j++){let x=-7+(j%5)*3.5,z=j<5?-5.6:5.2;if(theme==='winter'){ball(root,x,.06,z,.27,.06,.18,'#eff3ed')}else{for(let k=0;k<3;k++){let leaf=ball(root,x+k*.06,.10,z,.035,.13,.025,theme==='autumn'?'#c8a173':'#98b084');leaf.rotation.z=(k-1)*.3}}}
batchStatic(root);return{root,props,extras,actors,palette:p};}
